function pageWindow(items, page, size) {
  if (!Number.isSafeInteger(size) || size <= 0) throw new RangeError('size must be a positive safe integer');
  if (!Number.isSafeInteger(page)) throw new RangeError('page must be a safe integer');
  const totalPages = Math.max(1, Math.ceil(items.length / size));
  page = Math.max(1, Math.min(page, totalPages));
  const start = (page - 1) * size;
  return { page, totalPages, items: items.slice(start, start + size) };
}

